// The tests below pin the upstream registry the bench deploys next to Nexus
// (DEVDESK-505, step 2): a PVC, a Deployment and a ClusterIP Service, all named
// bench-upstream.

// upstreamObjectName is the name of the upstream object of the given kind.
func upstreamObjectName(kind string) string {
	if kind == "PersistentVolumeClaim" {
		return upstreamName + "-data"
	}
	return upstreamName
}

// TestRenderGoldenHoldsEveryDocument fails while the golden file still holds the
// four Nexus documents: regenerate it with
//
//	go test ./internal/nexusbench -run TestRenderGolden -update
//
// and read the diff, which must only add the three upstream documents.
func TestRenderGoldenHoldsEveryDocument(t *testing.T) {
	raw, err := os.ReadFile(goldenDefault)
	if err != nil {
		t.Fatal(err)
	}
	got := decodeStream(t, raw)
	if !reflect.DeepEqual(got.kinds, wantKinds) {
		t.Errorf("%s holds the kinds %v, want %v", goldenDefault, got.kinds, wantKinds)
	}
}

