// writeDatasetLayout writes the whole data set into a fresh directory.
func writeDatasetLayout(t *testing.T) (dir string, images []DatasetImage, refs []string) {
	t.Helper()
	images = Dataset()
	if len(images) == 0 {
		t.Fatal("Dataset() is empty")
	}
	dir = t.TempDir()
	refs, err := WriteLayout(dir, images)
	if err != nil {
		t.Fatalf("WriteLayout: %v", err)
	}
	return dir, images, refs
