			var fileModes []int64
			var files []string
			tr := tar.NewReader(bytes.NewReader(layer))
			for {
				h, err := tr.Next()
				if errors.Is(err, io.EOF) {
					break
				}
				if err != nil {
					t.Fatalf("the layer is not a tar archive: %v", err)
				}
